static void save(const std::filesystem::path& p,const QByteArray& data){QFile f(QString::fromStdWString(p.wstring()));require(f.open(QIODevice::WriteOnly|QIODevice::Truncate)&&f.write(data)==data.size(),"owned loop fixture/evidence write");}
