static ON_NurbsCurve circle(){ON_NurbsCurve n;require(ON_Circle(ON_xy_plane,5).GetNurbForm(n),"loop NURBS circle");n.ChangeDimension(2);return n;}
static ON_PolylineCurve polyline(){ON_Polyline points;for(auto p:{ON_3dPoint(-5,-5,0),ON_3dPoint(5,-5,0),ON_3dPoint(5,5,0),ON_3dPoint(-5,5,0),ON_3dPoint(-5,-5,0)})points.Append(p);ON_PolylineCurve c(points);c.ChangeDimension(2);return c;}
static std::unique_ptr<ON_PolyCurve> mixed(){auto owned=std::make_unique<ON_PolyCurve>();auto& c=*owned;
    auto line=new ON_LineCurve(ON_3dPoint(-5,-5,0),ON_3dPoint(5,-5,0));line->ChangeDimension(2);line->SetDomain(2,7);line->SetUserString(L"Child",L"Original native line");require(c.Append(line),"append native line");
    auto n=new ON_NurbsCurve(2,false,2,2);n->SetCV(0,ON_3dPoint(5,-5,0));n->SetCV(1,ON_3dPoint(5,5,0));n->SetKnot(0,11);n->SetKnot(1,13);n->SetUserString(L"Child",L"Original native NURBS");require(c.Append(n),"append native NURBS");
    auto nested=new ON_PolyCurve;auto top=new ON_LineCurve(ON_3dPoint(5,5,0),ON_3dPoint(-5,5,0));top->ChangeDimension(2);require(nested->Append(top),"nested line");ON_Polyline left;left.Append(ON_3dPoint(-5,5,0));left.Append(ON_3dPoint(-5,-5,0));auto side=new ON_PolylineCurve(left);side->ChangeDimension(2);side->SetUserString(L"Child",L"Original native polyline");require(nested->Append(side)&&c.Append(nested),"nested native polycurve");
    double t[]{101,111,151,211};require(c.SetParameterization(t)&&c.IsValid()&&c.IsClosed(),"polycurve independent segment domains");return owned;
}
